      backup_text =
        "# Nutrient Tracker #\n\n\
         # Soil management for sustainable moonlight farming. Nutrients run \
         0-100: #\n\
         # N = nitrogen (leafy growth), P = phosphorus (roots), K = potassium \
         (health). #\n\n\
         type Soil = (\n\
         n = Int,\n\
         p = Int,\n\
         k = Int\n\
         ) in\n\n\
         # The mystical crops of the night garden. Duskwheat fixes nitrogen \
         and #\n\
         # Nightshade restores it as a cover crop; Moonmelon is a heavy feeder \
         and #\n\
         # Starfruit draws on everything evenly. #\n\
         type Crop =\n\
         + Duskwheat\n\
         + Moonmelon\n\
         + Starfruit\n\
         + Nightshade\n\
         in\n\n\
         # A garden plot has soil state, optionally a growing crop, and a \
         season #\n\
         type Model = (\n\
         soil = Soil,\n\
         crop = +None +Some(Crop),\n\
         season = Int\n\
         ) in\n\n\
         # Planting needs bare ground; harvesting applies the crop's nutrient #\n\
         # effects; composting boosts everything; a season change settles the \
         soil. #\n\
         type Action =\n\
         + Plant(Crop)\n\
         + Harvest\n\
         + Compost\n\
         + SeasonChange\n\
         in\n\n\
         let clamp(x: Int): Int =\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         let balancedSoil: Soil = (n = 60, p = 60, k = 60) in\n\n\
         let init: Model = (\n\
         soil = balancedSoil,\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\n\
         # Establishing a crop costs a little of what it needs most #\n\
         let plantingCost(s: Soil, crop: Crop): Soil =\n\
         case crop\n\
         | Duskwheat => (n = s.n, p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         | Moonmelon => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k \
         - 5))\n\
         | Starfruit => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k \
         - 5))\n\
         | Nightshade => (n = s.n, p = clamp(s.p - 3), k = clamp(s.k - 3))\n\
         end\n\
         in\n\n\
         # Harvesting is the main nutrient exchange: crops deplete or restore #\n\
         let harvestEffect(s: Soil, crop: Crop): Soil =\n\
         case crop\n\
         | Duskwheat =>\n\
         # Nitrogen fixer: restores N, uses some P and K #\n\
         (n = clamp(s.n + 15), p = clamp(s.p - 10), k = clamp(s.k - 10))\n\
         | Moonmelon =>\n\
         # Heavy N feeder: depletes nitrogen significantly #\n\
         (n = clamp(s.n - 30), p = clamp(s.p - 10), k = clamp(s.k - 15))\n\
         | Starfruit =>\n\
         # Balanced consumer: moderate depletion across all #\n\
         (n = clamp(s.n - 15), p = clamp(s.p - 15), k = clamp(s.k - 15))\n\
         | Nightshade =>\n\
         # Cover crop turned under: major N restoration #\n\
         (n = clamp(s.n + 20), p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         end\n\
         in\n\n\
         let applyCompost(s: Soil): Soil =\n\
         (n = clamp(s.n + 10), p = clamp(s.p + 10), k = clamp(s.k + 10))\n\
         in\n\n\
         let seasonSettle(s: Soil): Soil =\n\
         (n = clamp(s.n - 3), p = clamp(s.p - 2), k = clamp(s.k - 2))\n\
         in\n\n\
         let update(model: Model, action: Action): Model =\n\
         case action\n\
         # A crop can only go into bare ground #\n\
         | Plant(crop) =>\n\
         case model.crop\n\
         | Some(_) => model\n\
         | None =>\n\
         (\n\
         soil = plantingCost(model.soil, crop),\n\
         crop = Some(crop),\n\
         season = model.season\n\
         )\n\
         end\n\
         # Harvesting bare ground does nothing #\n\
         | Harvest =>\n\
         case model.crop\n\
         | None => model\n\
         | Some(crop) =>\n\
         (\n\
         soil = harvestEffect(model.soil, crop),\n\
         crop = None,\n\
         season = model.season\n\
         )\n\
         end\n\
         | Compost =>\n\
         (\n\
         soil = applyCompost(model.soil),\n\
         crop = model.crop,\n\
         season = model.season\n\
         )\n\
         | SeasonChange =>\n\
         (\n\
         soil = seasonSettle(model.soil),\n\
         crop = model.crop,\n\
         season = model.season + 1\n\
         )\n\
         end\n\
         in\n\n\
         # ===== VIEW HELPERS ===== #\n\n\
         let seasonName(s: Int): String =\n\
         let phase = int_mod(s - 1, 4) in\n\
         if phase == 0 then \"Spring\"\n\
         else if phase == 1 then \"Summer\"\n\
         else if phase == 2 then \"Autumn\"\n\
         else \"Winter\"\n\
         in\n\n\
         let seasonEmoji(s: Int): String =\n\
         let phase = int_mod(s - 1, 4) in\n\
         if phase == 0 then \"\240\159\140\177\"\n\
         else if phase == 1 then \"\240\159\140\153\"\n\
         else if phase == 2 then \"\240\159\141\130\"\n\
         else \"\226\157\132\239\184\143\"\n\
         in\n\n\
         let cropName(c: Crop): String =\n\
         case c\n\
         | Duskwheat => \"Duskwheat\"\n\
         | Moonmelon => \"Moonmelon\"\n\
         | Starfruit => \"Starfruit\"\n\
         | Nightshade => \"Nightshade\"\n\
         end\n\
         in\n\n\
         let cropEmoji(c: Crop): String =\n\
         case c\n\
         | Duskwheat => \"\240\159\140\190\"\n\
         | Moonmelon => \"\240\159\141\136\"\n\
         | Starfruit => \"\240\159\140\159\"\n\
         | Nightshade => \"\240\159\141\135\"\n\
         end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         # Shared style values, on the editor's own palette #\n\
         let cardBg = (\"background\", \"var(--T2)\") in\n\
         let borderStyle = (\"border\", \"1px solid var(--BR1)\") in\n\
         let sidePad = (\"padding\", \"0.7em 1em\") in\n\
         let ruleTop = (\"border-top\", \"1px solid var(--BR1)\") in\n\n\
         # Section label: uppercase micro-caps, as in Hazel's own panels #\n\
         let sectionLabel(text: String): HTML =\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"),\n\
         (\"text-transform\", \"uppercase\"), (\"margin-bottom\", \"0.5em\")])],\n\
         [Text(text)])\n\
         in\n\n\
         # Nutrient bar: label, value 0-100, color #\n\
         let nutrientBar(label: String, value: Int, color: String): HTML =\n\
         let widthPct = string_of_int(value) ++ \"%\" in\n\
         Div(\n\
         [Style([(\"margin-bottom\", \"0.5em\")])],\n\
         [\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \
         \"space-between\"),\n\
         (\"margin-bottom\", \"0.2em\")])],\n\
         [\n\
         Span([Style([(\"color\", \"var(--BR3)\")])], [Text(label)]),\n\
         Span([Style([(\"color\", color), (\"font-weight\", \"bold\")])],\n\
         [Text(string_of_int(value) ++ \"/100\")])\n\
         ]\n\
         ),\n\
         Div(\n\
         [Style([(\"width\", \"100%\"), (\"height\", \"10px\"), \
         (\"background\", \"var(--SAND)\"),\n\
         (\"border-radius\", \"3px\"), (\"overflow\", \"hidden\"),\n\
         (\"border\", \"1px solid var(--BR1)\")])],\n\
         [\n\
         Div(\n\
         [Style([(\"width\", widthPct), (\"height\", \"100%\"), \
         (\"background\", color),\n\
         (\"transition\", \"width 0.3s\")])],\n\
         []\n\
         )\n\
         ]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         # One neutral button everywhere; `accent` marks the primary action #\n\
         let actionButton(label: String, action: Action, accent: Bool): HTML =\n\
         Button(\n\
         [\n\
         OnClick(action),\n\
         Style([\n\
         (\"padding\", \"0.35em 0.6em\"), (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"), (\"font-size\", \"0.85em\"),\n\
         (\"font-family\", \"inherit\"), (\"text-align\", \"left\"),\n\
         (\"white-space\", \"nowrap\"),\n\
         (\"background\", if accent then \"var(--G0)\" else \"var(--T1)\"),\n\
         (\"color\", if accent then \"var(--SAND)\" else \"var(--STONE)\"),\n\
         (\"border\", if accent then \"1px solid var(--G0)\" else \"1px solid \
         var(--BR1)\")\n\
         ])\n\
         ],\n\
         [Text(label)]\n\
         )\n\
         in\n\n\
         let buttonGrid(children: [HTML]): HTML =\n\
         Div(\n\
         [Style([(\"display\", \"grid\"), (\"grid-template-columns\", \"1fr \
         1fr\"), (\"gap\", \"0.4em\")])],\n\
         children\n\
         )\n\
         in\n\n\
         # Only these two read the model, so only they stay inside view #\n\
         let view(model: Model): HTML =\n\
         let cropDisplay: HTML =\n\
         case model.crop\n\
         | None =>\n\
         Div(\n\
         [Style([(\"text-align\", \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.5em\")])], \
         [Text(\"\240\159\140\171\239\184\143\")]),\n\
         Div([Style([(\"color\", \"var(--BR3)\"), (\"margin-top\", \
         \"0.2em\")])],\n\
         [Text(\"Fallow \226\128\148 nothing planted\")])\n\
         ]\n\
         )\n\
         | Some(c) =>\n\
         Div(\n\
         [Style([(\"text-align\", \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.5em\")])], [Text(cropEmoji(c))]),\n\
         Div([Style([(\"font-weight\", \"bold\"), (\"color\", \"var(--BR4)\"), \
         (\"margin-top\", \"0.2em\")])],\n\
         [Text(cropName(c))]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \
         \"var(--BR3)\")])],\n\
         [Text(\"Currently growing\")])\n\
         ]\n\
         )\n\
         end\n\
         in\n\n\
         let plantButtons: [HTML] =\n\
         case model.crop\n\
         | Some(_) =>\n\
         [\n\
         Div(\n\
         [Style([(\"text-align\", \"center\"), (\"color\", \"var(--BR3)\"),\n\
         (\"font-size\", \"0.75em\"), (\"grid-column\", \"span 2\")])],\n\
         [Text(\"Harvest the field before planting again\")]\n\
         )\n\
         ]\n\
         | None =>\n\
         [\n\
         actionButton(\"\240\159\140\190 Duskwheat\", Plant(Duskwheat), false),\n\
         actionButton(\"\240\159\141\136 Moonmelon\", Plant(Moonmelon), false),\n\
         actionButton(\"\240\159\140\159 Starfruit\", Plant(Starfruit), false),\n\
         actionButton(\"\240\159\141\135 Nightshade\", Plant(Nightshade), false)\n\
         ]\n\
         end\n\
         in\n\n\
         Div(\n\
         [Style([\n\
         (\"max-width\", \"320px\"), (\"margin\", \"0 auto\"),\n\
         (\"font-family\", \"var(--code-font)\"), (\"font-size\", \"0.85em\"),\n\
         (\"background\", \"var(--SAND)\"), (\"color\", \"var(--STONE)\"),\n\
         borderStyle, (\"border-radius\", \"0.4em\"), (\"overflow\", \"hidden\")\n\
         ])],\n\
         [\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\"), (\"text-align\", \
         \"center\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.2em\"), (\"font-weight\", \"bold\"), \
         (\"color\", \"var(--BR4)\")])],\n\
         [Text(\"\240\159\140\153 Moonlit Soil Lab\")]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"), \
         (\"margin-top\", \"0.3em\")])],\n\
         [Text(\"Nutrient management for the night garden\")])\n\
         ]\n\
         ),\n\n\
         # Season indicator #\n\
         Div(\n\
         [Style([(\"text-align\", \"center\"), sidePad, cardBg, ruleTop,\n\
         (\"border-bottom\", \"1px solid var(--BR1)\")])],\n\
         [\n\
         Span([Style([(\"font-size\", \"1.2em\")])], \
         [Text(seasonEmoji(model.season))]),\n\
         Span(\n\
         [Style([(\"font-weight\", \"bold\"), (\"color\", \"var(--BR4)\"), \
         (\"margin-left\", \"0.5em\")])],\n\
         [Text(seasonName(model.season))]\n\
         ),\n\
         Span(\n\
         [Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"), \
         (\"margin-left\", \"0.5em\")])],\n\
         [Text(\"season \" ++ string_of_int(model.season))]\n\
         )\n\
         ]\n\
         ),\n\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [\n\
         sectionLabel(\"Soil Nutrients\"),\n\
         nutrientBar(\"N  Nitrogen\", model.soil.n, \"var(--G0)\"),\n\
         nutrientBar(\"P  Phosphorus\", model.soil.p, \"var(--TYP)\"),\n\
         nutrientBar(\"K  Potassium\", model.soil.k, \"oklch(65% 0.14 70)\")\n\
         ]\n\
         ),\n\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [sectionLabel(\"Current Crop\"), cropDisplay]\n\
         ),\n\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [sectionLabel(\"Plant\"), buttonGrid(plantButtons)]\n\
         ),\n\n\
         Div(\n\
         [Style([sidePad, ruleTop])],\n\
         [\n\
         sectionLabel(\"Actions\"),\n\
         # Three actions in a two-column grid: the odd one spans the row #\n\
         # rather than sitting alone in a column #\n\
         buttonGrid([\n\
         actionButton(\"\240\159\140\191 Harvest\", Harvest, true),\n\
         actionButton(\"\240\159\167\145\226\128\141\240\159\140\190 \
         Compost\", Compost, false),\n\
         Div([Style([(\"grid-column\", \"span 2\"), (\"display\", \"grid\")])],\n\
         [actionButton(\"\240\159\148\132 Next Season\", SeasonChange, false)])\n\
         ])\n\
         ]\n\
         ),\n\n\
         Div(\n\
         [Style([(\"padding\", \"0.6em 1em\"), (\"text-align\", \"center\"),\n\
         (\"color\", \"var(--BR3)\"), (\"font-size\", \"0.75em\"), ruleTop])],\n\
         [Text(\"N \" ++ string_of_int(model.soil.n)\n\
         ++ \"  P \" ++ string_of_int(model.soil.p)\n\
         ++ \"  K \" ++ string_of_int(model.soil.k))]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         # With (model, action) order, `update` already has fold_left's shape #\n\
         let run(plot: Model, actions: [Action]): Model =\n\
         fold_left(actions, update, plot)\n\
         in\n\n\
         hint \"planting sets the crop and costs a little soil\"\n\
         test\n\
         let p = update(init, Plant(Starfruit)) in\n\
         p.crop == Some(Starfruit) && p.soil.n < init.soil.n\n\
         end;\n\n\
         hint \"the plot holds one crop at a time\"\n\
         test\n\
         let p = run(init, [Plant(Moonmelon), Plant(Starfruit)]) in\n\
         p.crop == Some(Moonmelon)\n\
         end;\n\n\
         hint \"harvesting clears the plot, harvesting bare ground does \
         nothing\"\n\
         test\n\
         let harvested = run(init, [Plant(Moonmelon), Harvest]) in\n\
         let bare = update(init, Harvest) in\n\
         harvested.crop == None && bare == init\n\
         end;\n\n\
         hint \"a heavy feeder drains nitrogen, a cover crop puts it back\"\n\
         test\n\
         let afterMoonmelon = run(init, [Plant(Moonmelon), Harvest]) in\n\
         let afterNightshade = run(afterMoonmelon, [Plant(Nightshade), \
         Harvest]) in\n\
         afterMoonmelon.soil.n < init.soil.n - 20\n\
         && afterNightshade.soil.n > afterMoonmelon.soil.n\n\
         end;\n\n\
         hint \"compost boosts every nutrient, and nothing exceeds 100\"\n\
         test\n\
         let p = update(init, Compost) in\n\
         let rich: Model = (soil = (n = 95, p = 95, k = 95), crop = None, \
         season = 1) in\n\
         let capped = update(rich, Compost) in\n\
         p.soil.n > init.soil.n\n\
         && p.soil.p > init.soil.p\n\
         && p.soil.k > init.soil.k\n\
         && capped.soil.n == 100\n\
         && capped.soil.p == 100\n\
         && capped.soil.k == 100\n\
         end;\n\n\
         hint \"a season change advances the counter and settles the soil\"\n\
         test\n\
         let p = update(init, SeasonChange) in\n\
         p.season == 2 && p.soil.n < init.soil.n\n\
         end;\n\n\
         hint \"nutrients never fall below 0\"\n\
         test\n\
         let poor: Model = (soil = (n = 10, p = 10, k = 10), crop = None, \
         season = 1) in\n\
         let p = run(poor, [Plant(Moonmelon), Harvest]) in\n\
         p.soil.n >= 0 && p.soil.p >= 0 && p.soil.k >= 0\n\
         end;\n\n\
         # Nothing here issues a command, so `update` returns a bare Model and \
         is #\n\
         # lifted into the (Model, Cmd) shape the app tuple expects. #\n\n\
         let noCmd(f: (Model, Action) -> Model): (Model, Action) -> (Model, \
         Cmd) =\n\
         fun (model, action) -> (f(model, action), CmdNone)\n\
         in\n\n\
         ^^html_sidebar((init, noCmd(update), view, subs))\n";
      refractors = "()";
    } )
